#include "governance_test_support.h"
#include <functional>
#include <iostream>
using namespace football_owner;
using match_test::check;
namespace gt=governance_test;
int runOwnerGovernanceTests(){
 const std::vector<std::pair<const char*,std::function<void()>>> tests={
 {"activation is neutral and idempotent",[]{auto s=gt::basis();const auto before=gt::snapshot(s);const auto cash=s.club.finance.cashPence;initializeOwnerGovernance(s);check(before==gt::snapshot(s)&&s.fanTendency.trustScore==50&&s.club.finance.cashPence==cash,"activation replay");}},
 {"same seed relationship traits",[]{check(gt::snapshot(gt::basis())==gt::snapshot(gt::basis()),"nondeterministic traits");}},
 {"legacy match results are not rewarded",[]{auto s=staff_test::basis();gt::result(s,true);s.fixtures.back().date=s.currentDate;initializeOwnerGovernance(s);s.governanceClubs.at("home").nextReviewDate=s.currentDate.addDays(1);gt::day(s);check(s.fanTendency.trustScore==50,"retroactive reward");}},
 {"promise has no cash or trust reward",[]{auto s=gt::basis();const auto cash=s.club.finance.cashPence;gt::promise(s);check(s.club.finance.cashPence==cash&&s.fanTendency.trustScore==50&&s.ownerCases.size()==1,"free promise reward");}},
 {"invalid promise kind atomic",[]{auto s=gt::basis();auto b=gt::snapshot(s);check(!makeOwnerPromise(s,"home","guarantee_xi","home-1",28)&&b==gt::snapshot(s),"XI promise accepted");}},
 {"invalid promise duration atomic",[]{auto s=gt::basis();auto b=gt::snapshot(s);check(!makeOwnerPromise(s,"home","retain_player","home-1",1)&&b==gt::snapshot(s),"invalid duration");}},
 {"outsider contract refused",[]{auto s=gt::basis();check(!makeOwnerPromise(s,"home","retain_player","away-1",28),"outsider");}},
 {"duplicate promise refused",[]{auto s=gt::basis();gt::promise(s);auto b=gt::snapshot(s);check(!makeOwnerPromise(s,"home","retain_player","home-1",28)&&b==gt::snapshot(s),"duplicate");}},
 {"three concurrent promise cap",[]{auto s=gt::basis();for(int n=1;n<=3;++n)gt::promise(s,"retain_player","home-"+std::to_string(n));check(!makeOwnerPromise(s,"home","retain_player","home-4",28),"unbounded promises");}},
 {"retention only completes on due date",[]{auto s=gt::basis();gt::promise(s);gt::day(s,27);check(s.ownerCases.front().status=="promised","early completion");gt::day(s);check(s.ownerCases.front().status=="fulfilled"&&s.fanTendency.trustScore==52,"due completion");}},
 {"positive promise reward capped per club 28 days",[]{auto s=gt::basis();for(int n=1;n<=3;++n)gt::promise(s,"retain_player","home-"+std::to_string(n));gt::day(s,28);check(s.fanTendency.trustScore==54,"reward farm");}},
 {"same date completion not replayed",[]{auto s=gt::basis();gt::promise(s);gt::day(s,28);auto b=gt::snapshot(s);processOwnerGovernanceDay(s);check(b==gt::snapshot(s),"same date replay");}},
 {"withdraw costs once",[]{auto s=gt::basis();gt::promise(s);auto id=s.ownerCases.front().id;check(withdrawOwnerPromise(s,id)&&s.fanTendency.trustScore==46,"withdraw");auto b=gt::snapshot(s);check(!withdrawOwnerPromise(s,id)&&b==gt::snapshot(s),"double withdraw");}},
 {"closed promise still prevents rapid recreation",[]{auto s=gt::basis();gt::promise(s);withdrawOwnerPromise(s,s.ownerCases.front().id);check(!makeOwnerPromise(s,"home","retain_player","home-1",28),"closed cooldown");}},
 {"hire promise needs real employment",[]{auto s=gt::basis();gt::promise(s,"hire_medical","");gt::day(s);check(s.ownerCases.front().status=="promised","fake hire");staff_test::hire(s,"staff-model:medical:1",{"medical"});gt::day(s);check(s.ownerCases.front().status=="fulfilled","real hire ignored");}},
 {"filled role cannot farm promise",[]{auto s=gt::basis();staff_test::hire(s,"staff-model:medical:1",{"medical"});check(!makeOwnerPromise(s,"home","hire_medical","",28),"already filled");}},
 {"missed hire deadline breaks promise",[]{auto s=gt::basis();gt::promise(s,"hire_medical","");gt::day(s,28);check(s.ownerCases.front().status=="broken"&&s.fanTendency.trustScore==46,"missed deadline");}},
 {"late hire is not retroactive fulfilment",[]{auto s=gt::basis();gt::promise(s,"hire_medical","");s.currentDate=s.currentDate.addDays(29);staff_test::hire(s,"staff-model:medical:1",{"medical"});processOwnerGovernanceDay(s);check(s.ownerCases.front().status=="broken","late evidence");}},
 {"renewal needs 180 additional days",[]{auto s=gt::basis();gt::promise(s,"renew_player","home-1");for(auto& c:s.playerContracts)if(c.playerId=="home-1")c.endDate=c.endDate.addDays(1);gt::day(s);check(s.ownerCases.front().status=="promised","one-day extension");for(auto& c:s.playerContracts)if(c.playerId=="home-1")c.endDate=c.endDate.addDays(180);gt::day(s);check(s.ownerCases.front().status=="fulfilled","real renewal");}},
 {"renewal due beyond contract refused",[]{auto s=gt::basis();for(auto& c:s.playerContracts)if(c.playerId=="home-1")c.endDate=s.currentDate.addDays(5);check(!makeOwnerPromise(s,"home","renew_player","home-1",28),"impossible timing");}},
 {"departure breaks retention",[]{auto s=gt::basis();gt::promise(s);for(auto& c:s.playerContracts)if(c.playerId=="home-1")c.clubId="away";gt::day(s);check(s.ownerCases.front().status=="broken","departure");}},
 {"manager appointment itself not promised success",[]{auto s=gt::basis();gt::promise(s,"keep_manager","staff-opening-manager:home");gt::day(s);check(s.ownerCases.front().status=="promised","early manager success");}},
 {"manager dismissal breaks support",[]{auto s=gt::basis();gt::promise(s,"keep_manager","staff-opening-manager:home");auto q=quoteStaffAction(s,"home","staff-opening-manager:home","dismiss");check(confirmStaffAction(s,q),"dismiss");gt::day(s);check(s.ownerCases.front().status=="broken","dismiss ignored");}},
 {"manager resignation cancels support without blame",[]{auto s=gt::basis();gt::promise(s,"keep_manager","staff-opening-manager:home");s.staffPolicies.at("home").resignationDate=s.currentDate.addDays(1);gt::day(s);check(s.ownerCases.front().status=="cancelled"&&s.fanTendency.trustScore==50,"resignation blamed");}},
 {"wage promise requires actual arrears",[]{auto s=gt::basis();check(!makeOwnerPromise(s,"home","pay_wages","",28),"fictional debt");}},
 {"wage promise follows actual settlement",[]{auto s=gt::basis();gt::unpaid(s);gt::promise(s,"pay_wages","");gt::day(s);check(s.ownerCases.front().status=="fulfilled","settlement ignored");}},
 {"first public statement no reward",[]{auto s=gt::basis();check(declareOwnerDirection(s,"home","youth")&&s.fanTendency.trustScore==50,"statement reward");}},
 {"statement cooldown is atomic",[]{auto s=gt::basis();declareOwnerDirection(s,"home","youth");auto b=gt::snapshot(s);check(!declareOwnerDirection(s,"home","stability")&&b==gt::snapshot(s),"statement spam");}},
 {"quick change has consistency consequence",[]{auto s=gt::basis();declareOwnerDirection(s,"home","youth");gt::day(s,7);check(declareOwnerDirection(s,"home","stability")&&s.fanTendency.trustScore==48,"no change consequence");}},
 {"same direction repeated does not award",[]{auto s=gt::basis();declareOwnerDirection(s,"home","youth");gt::day(s,7);check(!declareOwnerDirection(s,"home","youth")&&s.fanTendency.trustScore==50,"same declaration");}},
 {"unknown direction refused",[]{auto s=gt::basis();check(!declareOwnerDirection(s,"home","guarantee_trophy"),"unknown");}},
 {"internal actions leave scores unchanged",[]{auto s=gt::basis();OwnerActionImpact i;i.fanTrustDelta=i.reputationDelta=i.youthPreferenceDelta=5;for(const auto* k:{"target_scouting_directive","range_scouting_directive","set_squad_opinion","clear_squad_opinion","approve_transfer","reject_transfer","call_operating_meeting"})recordOwnerAction(s,k,"test","","","",i);check(s.ownerActionLog.size()==7&&s.fanTendency.trustScore==50&&s.ownerReputation.overallScore==50&&s.fanTendency.youthDevelopmentPreference==50,"internal farm");}},
 {"observed sporting success improves trust",[]{auto s=gt::basis();gt::result(s,true);s.governanceClubs.at("home").nextReviewDate=s.currentDate.addDays(1);gt::day(s);check(s.fanTendency.trustScore>50,"result no feedback");}},
 {"AI fans use same sporting result",[]{auto s=gt::basis();gt::result(s,true);s.governanceClubs.at("away").nextReviewDate=s.currentDate.addDays(1);gt::day(s);check(governanceFans(s,"away")->trustScore<50,"AI immune");}},
 {"skepticism damps success",[]{auto a=gt::basis(),b=a;a.fanTendency.skepticismScore=100;b.fanTendency.skepticismScore=0;for(auto* s:{&a,&b}){gt::result(*s,true);s->governanceClubs.at("home").nextReviewDate=s->currentDate.addDays(1);gt::day(*s);}check(a.fanTendency.trustScore<b.fanTendency.trustScore,"skepticism unused");}},
 {"patience damps defeat",[]{auto a=gt::basis(),b=a;a.fanTendency.patienceScore=100;b.fanTendency.patienceScore=0;for(auto* s:{&a,&b}){gt::result(*s,false);s->governanceClubs.at("home").nextReviewDate=s->currentDate.addDays(1);gt::day(*s);}check(a.fanTendency.trustScore>b.fanTendency.trustScore,"patience unused");}},
 {"match feedback counted once across reviews",[]{auto s=gt::basis();gt::result(s,true);s.governanceClubs.at("home").nextReviewDate=s.currentDate.addDays(1);gt::day(s);int trust=s.fanTendency.trustScore;gt::day(s,28);check(s.fanTendency.trustScore==trust,"match replay");}},
 {"low trust is not instant income penalty",[]{auto s=gt::basis();s.fanTendency.trustScore=10;gt::day(s,55);check(fanMatchIncomePercent(s,"home")==100,"instant punishment");}},
 {"persistent low trust reduces projected income and can recover",[]{auto s=gt::basis();s.fanTendency.trustScore=10;gt::day(s,57);check(fanMatchIncomePercent(s,"home")==90,"no consequence");auto f=match_test::fixture().fixtures.front();f.date=s.currentDate.addDays(1);s.fixtures.push_back(f);auto before=forecastCash(s,"home",7).modelIncomePence;s.fanTendency.trustScore=35;check(fanMatchIncomePercent(s,"home")==100&&forecastCash(s,"home",7).modelIncomePence>before,"recovery/forecast");}},
 {"morale affects own and AI match rating within two",[]{auto s=gt::basis();s.playerRelationships.at("home|home-1").morale=0;s.playerRelationships.at("away|away-1").morale=100;check(playerMoraleAdjustment(s,"home-1","home")==-2&&playerMoraleAdjustment(s,"away-1","away")==2,"morale bound");check(playerMoraleAdjustment(s,"home-1","away")==0,"wrong club morale");}},
 {"influence is derived without owner control",[]{auto s=gt::basis();gt::day(s,28);check(s.playerRelationships.at("home|home-1").influence>20,"hierarchy not evaluated");}},
 {"contract concern appears and is not auto accepted",[]{auto s=gt::basis();for(auto& c:s.playerContracts)if(c.playerId=="home-0")c.endDate=s.currentDate.addDays(100);gt::day(s,28);check(std::any_of(s.ownerCases.begin(),s.ownerCases.end(),[](const auto& c){return c.clubId=="home"&&c.status=="requested";}),"missing concern");}},
 {"request acceptance creates no contract rewrite",[]{auto s=gt::basis();for(auto& c:s.playerContracts)if(c.playerId=="home-0")c.endDate=s.currentDate.addDays(100);gt::day(s,28);auto c=s.ownerCases.front();check(respondOwnerCase(s,c.id,true,28,"")&&s.ownerCases.front().status=="promised","accept");check(directoryPlayer(s,c.subjectId,s.currentDate)->contract->endDate==c.baselineContractEnd,"hidden renewal");}},
 {"request invalid decline is atomic",[]{auto s=gt::basis();for(auto& c:s.playerContracts)if(c.playerId=="home-0")c.endDate=s.currentDate.addDays(100);gt::day(s,28);auto before=gt::snapshot(s);check(!respondOwnerCase(s,s.ownerCases.front().id,false,28,"magic")&&before==gt::snapshot(s),"invalid refusal");}},
 {"request expires without contract or cash rewrite",[]{auto s=gt::basis();for(auto& c:s.playerContracts)if(c.playerId=="home-0")c.endDate=s.currentDate.addDays(100);gt::day(s,43);check(s.ownerCases.front().status=="expired","request never expires");}},
 {"split reconstruction deterministic",[]{auto a=gt::basis();gt::promise(a);auto b=a;gt::day(a,56);gt::day(b,17);auto reloaded=b;gt::day(reloaded,39);check(gt::snapshot(a)==gt::snapshot(reloaded),"split divergence");}},
 {"influence includes active competition season minutes",[]{auto a=gt::basis(),b=a;MatchResult r;r.seasonId="league-1992";r.home.clubId="home";r.home.players.emplace_back();r.home.players.back().playerId="home-1";r.home.players.back().minutes=900;a.matchResults.push_back(r);for(auto* s:{&a,&b}){s->governanceClubs.at("home").nextReviewDate=s->currentDate.addDays(1);gt::day(*s);}check(a.playerRelationships.at("home|home-1").influence==b.playerRelationships.at("home|home-1").influence+10,"active minutes ignored");}},
 {"low trust reduces real home income once",[]{auto s=gt::basis();s.fanTendency.trustScore=10;gt::day(s,57);auto healthy=s;healthy.fanTendency.trustScore=35;gt::result(s,true);gt::result(healthy,true);gt::day(s);gt::day(healthy);Money low=0,full=0;for(const auto& t:s.operatingTransactions)if(t.clubId=="home"&&t.category=="matchday_income")low+=t.amountPence;for(const auto& t:healthy.operatingTransactions)if(t.clubId=="home"&&t.category=="matchday_income")full+=t.amountPence;check(full>0&&low==full*90/100,"actual income not discounted");const auto cash=s.club.finance.cashPence;settleOperatingDay(s);check(s.club.finance.cashPence==cash,"income replay");}},
 {"AI and owner promise failures change fans equally",[]{auto s=gt::basis();s.governanceClubs.at("away").aiFans=s.fanTendency;gt::promise(s);check(makeOwnerPromise(s,"away","retain_player","away-1",28),"AI promise");const auto first=s.ownerCases[0].id,second=s.ownerCases[1].id;check(withdrawOwnerPromise(s,first)&&withdrawOwnerPromise(s,second),"withdraw");const auto& ai=*governanceFans(s,"away");check(ai.trustScore==s.fanTendency.trustScore&&ai.patienceScore==s.fanTendency.patienceScore&&ai.skepticismScore==s.fanTendency.skepticismScore,"unequal fan model");}},
 {"missing renewal evidence baseline rejected",[]{auto s=gt::basis();gt::promise(s,"renew_player");s.ownerCases.back().baselineContractEnd.reset();check(!validateOwnerGovernance(s).empty(),"missing baseline");}},
 {"invalid morale rejected",[]{auto s=gt::basis();s.playerRelationships.begin()->second.morale=101;check(!validateOwnerGovernance(s).empty(),"bad morale");}},
 {"duplicate match IDs rejected",[]{auto s=gt::basis();s.governanceMatchIds={"duplicate","duplicate"};check(!validateOwnerGovernance(s).empty(),"duplicate match");}},
 {"unknown promise state rejected",[]{auto s=gt::basis();gt::promise(s);s.ownerCases.front().status="fake";check(!validateOwnerGovernance(s).empty(),"bad status");}},
 {"missing club state rejected",[]{auto s=gt::basis();s.governanceClubs.clear();check(!validateOwnerGovernance(s).empty(),"empty state silently regenerated");}}
 };
 int failed=0;for(const auto& [name,run]:tests)try{run();std::cout<<"[PASS] governance "<<name<<'\n';}catch(const std::exception& e){++failed;std::cerr<<"[FAIL] governance "<<name<<": "<<e.what()<<'\n';}
 std::cout<<tests.size()-failed<<'/'<<tests.size()<<" governance tests passed\n";return failed;
}
